<section class="wrap section"><div class="section-head"><div><span class="eyebrow maple-text"><?=icon('leaf')?> BUY CANADIAN. KEEP IT INDEPENDENT.</span><h1 class="page-title">Good things.<br><em>Closer to home.</em></h1><p class="lead">A community-built directory of Canadian connections.<br>Local roots, independent minds, and sources you can check.</p></div><a class="button" href="/directory/submit">+ Share a discovery</a></div><div class="note">A listing is a community-sourced lead, not a certification. Canadian-owned, made in Canada, and Canadian-hosted mean different things. Check the linked source and the specific product before buying.</div><form class="searchbar" action="/directory"><label class="sr-only" for="directory-search">Search directory</label><input id="directory-search" name="q" value="<?=esc($q)?>" placeholder="Find a maker, service, province, or alternative…"><?php select_field('Connection','claim',[''=>'All connections','Canadian-owned'=>'Canadian-owned','Made in Canada'=>'Made in Canada','Canadian-hosted'=>'Canadian-hosted','Community organization'=>'Community organization'],$claim);?><button class="button outline">Search</button></form><div class="entry-grid"><?php foreach($listings as $l):?><article class="directory-card"><span class="app-icon"><?=icon('leaf')?></span><?=tag($l['claim'],'maple-tag')?><h3><?=esc($l['name'])?></h3><p><?=esc($l['notes'])?></p><div class="entry-meta"><span><?=esc($l['province'])?> · <?=esc($l['category'])?></span></div><div class="actions"><a class="text-link" href="<?=esc($l['website'])?>" rel="noopener noreferrer">Visit website ↗</a><a href="<?=esc($l['evidence_url'])?>" rel="noopener noreferrer">Check source</a></div><small>Listing reviewed <?=esc(substr($l['reviewed_at'],0,10))?> · source may change</small></article><?php endforeach;if(!$listings)empty_state('Good discoveries start with you.','No matching listings yet. Suggest a Canadian business or community with a source link.','/directory/submit','Share a discovery');?></div></section>
